import { mkdirSync, mkdtempSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join, sep } from "node:path";

import { afterEach, describe, expect, it } from "vitest";

import { GENERATOR_VERSION, sha256Hex, withGeneratedHeader } from "../../src/core";
import { checkGeneratedFiles, generatedComponents, sourceFilesOf } from "../../src/server/generated-files";
import { PATHS } from "../../src/shared/paths";

/**
 * Livello 3 della CI (Story 2.24): hash e versione dei file `@generated` del
 * repo. Hash che non torna = blocco col path; versione diversa con hash
 * giusto = avviso col path.
 */

const roots: string[] = [];

function tempRoot(): string {
  const root = mkdtempSync(join(tmpdir(), "pds-generated-"));
  roots.push(root);
  return root;
}

afterEach(() => {
  for (const root of roots.splice(0)) rmSync(root, { recursive: true, force: true });
});

function put(root: string, path: string, content: string): void {
  mkdirSync(join(root, path, ".."), { recursive: true });
  writeFileSync(join(root, path), content);
}

const BODY = 'export const x = "x";\n';

describe("livello 3 — sul repo vero", () => {
  it("la scansione vede davvero packages/ e apps/", () => {
    const files = sourceFilesOf(PATHS.repoRoot).map((file) => file.slice(PATHS.repoRoot.length + 1).split(sep).join("/"));
    expect(files.some((file) => file.startsWith("packages/"))).toBe(true);
    expect(files.some((file) => file.startsWith("apps/"))).toBe(true);
    expect(files.some((file) => file.split("/").includes("node_modules"))).toBe(false);
  });

  it("nessun file @generated del repo è stato modificato a mano", () => {
    const findings = checkGeneratedFiles(PATHS.repoRoot);
    // Una GENERATOR_VERSION vecchia non ferma la CI, ma si vede nell'output.
    for (const finding of findings.filter((item) => item.level === "avviso")) console.warn(`pds livello 3 — avviso: ${finding.where}: ${finding.message}`);
    expect(findings.filter((finding) => finding.level === "blocco")).toEqual([]);
  });
});

describe("livello 3 — rosso/verde su una cartella temporanea", () => {
  it("file generato intatto → nessun esito", () => {
    const root = tempRoot();
    put(root, "packages/ui/src/domains/badge/Badge.styles.ts", withGeneratedHeader(BODY));
    put(root, "apps/web/src/x.generated.tsx", withGeneratedHeader(BODY));
    expect(checkGeneratedFiles(root)).toEqual([]);
  });

  it("hash rotto (file editato a mano) → blocco che nomina il file", () => {
    const root = tempRoot();
    put(root, "packages/ui/src/domains/badge/Badge.styles.ts", `${withGeneratedHeader(BODY)}// ritocco a mano\n`);
    put(root, "apps/web/src/ok.ts", withGeneratedHeader(BODY));
    const findings = checkGeneratedFiles(root);
    expect(findings).toHaveLength(1);
    expect(findings[0]).toMatchObject({ level: "blocco", where: "packages/ui/src/domains/badge/Badge.styles.ts" });
  });

  it("anche in apps/ → blocco col path", () => {
    const root = tempRoot();
    put(root, "apps/web/src/x.tsx", withGeneratedHeader(BODY).replace('"x"', '"y"'));
    expect(checkGeneratedFiles(root)).toMatchObject([{ level: "blocco", where: "apps/web/src/x.tsx" }]);
  });

  it("versione vecchia (header `pds 0`) con hash giusto → avviso col path", () => {
    const root = tempRoot();
    expect(GENERATOR_VERSION).not.toBe("0");
    put(root, "packages/ui/src/domains/badge/Badge.stories.tsx", `// @generated pds 0 sha256:${sha256Hex(BODY)} — non modificare a mano\n${BODY}`);
    expect(checkGeneratedFiles(root)).toMatchObject([{ level: "avviso", where: "packages/ui/src/domains/badge/Badge.stories.tsx" }]);
  });

  it("versione vecchia e hash rotto → blocco", () => {
    const root = tempRoot();
    put(root, "packages/a.ts", `// @generated pds 0 sha256:${sha256Hex(BODY)} — non modificare a mano\n${BODY}// a mano\n`);
    expect(checkGeneratedFiles(root)).toMatchObject([{ level: "blocco", where: "packages/a.ts" }]);
  });

  it.each([
    ["hash troncato", `// @generated pds 1 sha256:abc — non modificare a mano\n${BODY}`],
    ["refuso", `// @generated pds 1 sha265:${sha256Hex(BODY)} — non modificare a mano\n${BODY}`],
    ["intestazione senza testo finale", `// @generated pds 1 sha256:${sha256Hex(BODY)}\n${BODY}`],
  ])("marker rovinato (%s) → blocco col path", (_label, content) => {
    const root = tempRoot();
    put(root, "packages/ui/src/domains/badge/Badge.styles.ts", content);
    expect(checkGeneratedFiles(root)).toMatchObject([{ level: "blocco", where: "packages/ui/src/domains/badge/Badge.styles.ts" }]);
  });

  it("un altro generatore (@generated senza pds) non è un marker di pds", () => {
    const root = tempRoot();
    put(root, "packages/tokens/src/tokens.generated.ts", `/* @generated from Penpot design tokens — DO NOT EDIT BY HAND. */\n// @generated by other\n${BODY}`);
    expect(checkGeneratedFiles(root)).toEqual([]);
  });

  it("file senza marker, altre estensioni e cartelle escluse non si guardano", () => {
    const root = tempRoot();
    const broken = `${withGeneratedHeader(BODY)}// a mano\n`;
    put(root, "packages/ui/src/mine.ts", BODY);
    put(root, "packages/ui/src/readme.md", broken);
    for (const skipped of ["node_modules", "dist", ".next", "storybook-static"]) put(root, `packages/ui/${skipped}/x.ts`, broken);
    put(root, "other/x.ts", broken);
    expect(checkGeneratedFiles(root)).toEqual([]);
  });

  it("una root senza packages/ né apps/ → nessun esito", () => {
    expect(checkGeneratedFiles(tempRoot())).toEqual([]);
  });
});

describe("generatedComponents", () => {
  it("solo le cartelle con un <Comp>.styles.ts che ha il marker", () => {
    const root = tempRoot();
    put(root, "packages/ui/src/domains/badge/Badge.styles.ts", withGeneratedHeader(BODY));
    put(root, "packages/ui/src/domains/shop-card/ShopCard.styles.ts", BODY);
    put(root, "packages/ui/src/domains/card/Card.tsx", BODY);
    expect(generatedComponents(root)).toEqual(["badge"]);
    expect(generatedComponents(tempRoot())).toEqual([]);
  });
});
